INSERT INTO proposal_document_templates (key,name,description,sections,config)
VALUES ('scenario_composer','LOLA Proposal Composer','Global, event, experience and package defaults for composable proposals','[]', '{"global":{"intro":"Thank you for considering The Lola Booth for {{event_name}}. We’re excited to create an experience for your guests.","event_intro":"Here is a summary of the details we have so far. We are happy to adjust every detail.","why_us_title":"More Than a Photo Booth","why_us_intro":"Thoughtful presentation, friendly people and an experience built around your event.","close_title":"Let’s Create Something Memorable","close_body":"Thank you again for considering The Lola Booth. We look forward to creating memories with you and your guests.","next_steps_intro":"When you are ready, here is what happens next.","next_steps":["Review the proposal","Accept the proposal","Invoice is prepared","Deposit secures the date","Confirm final event details"],"terms_intro":"Final scope, availability and logistics are subject to the agreed proposal and invoice.","experience_intro_style":"Your selected experiences","investment_title":"A Simple, Transparent Investment","investment_intro":"Your selected experiences, packages and enhancements are itemized below.","optional_goal_section":"Activation Goals","optional_brand_section":"Brand Integration","why_items":[{"icon":"diamond","title":"Premium Experiences","body":"Thoughtful presentation for your guests."},{"icon":"people","title":"Professional Team","body":"Friendly people who help your event run smoothly."},{"icon":"camera","title":"Lasting Memories","body":"Moments to revisit after the event."},{"icon":"brush","title":"Thoughtful Details","body":"A clear plan around your chosen experiences."},{"icon":"gear","title":"Clear Coordination","body":"Event details and scope confirmed together."},{"icon":"heart","title":"Good People","body":"A team that cares about your celebration."}],"tagline":"Good people. Better photos.","media_ids":[]},"events":{"Wedding":{"tone":"warm, elevated, emotional, polished","intro":"Thank you for considering The Lola Booth for {{event_name}}. We’re excited about the opportunity to be part of your celebration and create unforgettable moments for you and your guests.","event_intro":"Here’s a summary of your celebration. If anything needs to be adjusted, just let us know. We’re happy to customize every detail.","why_us_title":"More Than a Photo Booth","close_title":"We’d Love to Be Part of Your Day","close_body":"Thank you again for considering The Lola Booth. We’re excited to bring our experiences to your wedding and create moments that last a lifetime."},"Birthday":{"tone":"celebratory, energetic, stylish","intro":"Thank you for considering The Lola Booth for {{event_name}}. We’d love to help make this celebration feel even more special with an interactive experience your guests will enjoy from start to finish.","event_intro":"Here’s what we have planned for the celebration. We can adjust any detail to match the vibe, guest count and vision for the event.","why_us_title":"Make the Celebration Unforgettable","close_title":"Let’s Make It a Celebration to Remember","close_body":"We’re excited about the opportunity to celebrate with you and create photos, videos and moments you’ll want to keep long after the party ends."},"Private Party":{"tone":"premium, flexible, personal","intro":"Thank you for considering The Lola Booth for {{event_name}}. We’re excited to create a polished, interactive experience designed around your guests and the atmosphere you want to create.","event_intro":"Below is a summary of the event details we have so far. Everything can be tailored as plans continue to come together.","why_us_title":"Designed Around Your Celebration","close_title":"Let’s Create Something Memorable","close_body":"We look forward to bringing a thoughtful guest experience to your celebration."},"Brand Activation":{"tone":"strategic, premium, business-focused","intro":"Thank you for considering The Lola Booth for {{event_name}}. We’re excited about the opportunity to create a high-energy, immersive photo and video experience designed to engage your audience, generate branded content and extend the reach of your activation.","event_intro":"Below is the activation brief and the experience configuration prepared for your event. Every element can be adapted to align with your campaign, brand standards and guest journey.","why_us_title":"More Than a Booth. A Brand Experience.","close_title":"We’d Love to Be Part of Your Activation","close_body":"Thank you for the opportunity to bring {{brand_name_or_client}} to life through an interactive guest experience. We’re ready to create a polished activation that engages your audience and delivers memorable branded content.","next_steps":["Review proposal","Approve experience configuration","Accept proposal","Invoice / deposit","Collect brand assets","Approve creative","Confirm production","Event execution"],"goals":["Guest engagement","Branded content capture","Social sharing","Memorable on-site experience"],"why_items":[{"icon":"diamond","title":"Premium Presentation","body":"An experience that complements your brand."},{"icon":"people","title":"Professional Team","body":"People who support your audience and event."},{"icon":"gear","title":"Reliable Execution","body":"Clear coordination from planning through delivery."},{"icon":"brush","title":"Brand Focus","body":"Scope aligned with your approved campaign brief."},{"icon":"camera","title":"Memorable Content","body":"Your selected experiences put guests at the center."},{"icon":"heart","title":"Good People","body":"A team that cares about your event."}]},"Corporate Event":{"tone":"professional, polished, business-friendly","intro":"Thank you for considering The Lola Booth for {{event_name}}. We’re excited to provide a polished photo and video experience that gives your guests an engaging, memorable addition to the event.","event_intro":"Below is a summary of the event and proposed experience configuration. We can adjust the setup, branding and service levels to fit your event requirements.","why_us_title":"Professional Experiences, Memorable Events","close_title":"We’re Ready to Support Your Event","close_body":"We look forward to coordinating an engaging guest experience for {{company_name}}."},"Other":{"tone":"neutral premium","intro":"Thank you for considering The Lola Booth for {{event_name}}. We’re excited to create a custom photo and video experience tailored to your event, your guests and your vision.","event_intro":"Here’s a summary of what we know so far. Every detail can be adjusted as the event continues to take shape.","why_us_title":"An Experience Built Around Your Event","close_title":"Let’s Create Something Great","close_body":"We look forward to creating an experience tailored to your vision."}},"experiences":{"360":{"personal":"A dynamic slow-motion video experience that gets everyone into the celebration.","business":"A high-energy branded video activation that puts your audience at the center of the content."},"glam":{"personal":"Studio-quality, magazine-ready portraits for you and your guests.","business":"A polished branded photo experience designed to capture premium guest content and create shareable brand moments."},"vogue":{"personal":"A fashion-forward editorial experience inspired by magazine style, giving your guests a dramatic moment in the spotlight.","business":"An editorial-style branded content experience designed for striking visual moments and guest engagement."},"audio":{"personal":"Give your guests a personal way to leave messages, stories and memories from the celebration.","Wedding":"Heartfelt, hilarious and unforgettable. Your guests leave voice messages, stories and well wishes you’ll treasure long after the event.","business":"An interactive voice experience for guest reactions, messages or event feedback."}},"packages":{}}'::jsonb)
